import os
from typing import Any, Dict, List, Optional

import boto3


def _field_value(value: Any) -> Optional[str]:
    if value is None:
        return None
    for attr in ("value", "text", "content"):
        if hasattr(value, attr):
            v = getattr(value, attr)
            if v is not None:
                return str(v)
    if isinstance(value, dict):
        for key in ("Value", "value", "Text", "text", "Content", "content"):
            if key in value and value[key] is not None:
                return str(value[key])
    return str(value)


def _normalize_item(item: Dict[str, Any]) -> Dict[str, Any]:
    normalized = {
        "description": None,
        "quantity": None,
        "unit_price": None,
        "amount": None,
    }
    for key, target in [
        ("Description", "description"),
        ("Item", "description"),
        ("Name", "description"),
        ("Quantity", "quantity"),
        ("UnitPrice", "unit_price"),
        ("Price", "unit_price"),
        ("Amount", "amount"),
        ("TotalPrice", "amount"),
    ]:
        if key in item and item[key] is not None:
            normalized[target] = _field_value(item[key])
    return normalized


def extract_receipt_fields(receipt_source: str) -> Dict[str, Any]:
    """
    Extract merchant, tax, total, and items from a receipt image/PDF using Amazon Textract AnalyzeExpense.

    receipt_source can be:
      - a local file path
      - an S3 URI in the form s3://bucket/key
    """
    textract = boto3.client("textract")

    if receipt_source.startswith("s3://"):
        _, _, rest = receipt_source.partition("s3://")
        bucket, _, key = rest.partition("/")
        response = textract.analyze_expense(
            Document={"S3Object": {"Bucket": bucket, "Name": key}}
        )
    else:
        with open(receipt_source, "rb") as f:
            response = textract.analyze_expense(Document={"Bytes": f.read()})

    result = {
        "merchant": None,
        "tax": None,
        "total": None,
        "items": [],
    }

    expense_docs = response.get("ExpenseDocuments", []) or []
    if not expense_docs:
        return result

    doc = expense_docs[0]

    summary_fields = doc.get("SummaryFields", []) or []
    for field in summary_fields:
        ftype = (field.get("Type") or {}).get("Text")
        value = (field.get("ValueDetection") or {}).get("Text")
        if not ftype or value is None:
            continue

        ftype_upper = ftype.upper()
        if ftype_upper in {"VENDOR_NAME", "MERCHANT_NAME", "SUPPLIER_NAME"} and not result["merchant"]:
            result["merchant"] = value
        elif ftype_upper in {"TOTAL", "AMOUNT_DUE", "INVOICE_RECEIPT_TOTAL"} and not result["total"]:
            result["total"] = value
        elif ftype_upper in {"TAX", "TAX_AMOUNT", "SALES_TAX"} and not result["tax"]:
            result["tax"] = value

    # Fallbacks from line-item groups
    line_item_groups = doc.get("LineItemGroups", []) or []
    for group in line_item_groups:
        for line_item in group.get("LineItems", []) or []:
            item_dict = {}
            for field in line_item.get("LineItemExpenseFields", []) or []:
                key = (field.get("Type") or {}).get("Text")
                value = (field.get("ValueDetection") or {}).get("Text")
                if key and value is not None:
                    item_dict[key] = value
            normalized_item = _normalize_item(item_dict)
            if any(v is not None for v in normalized_item.values()):
                result["items"].append(normalized_item)

    # Additional fallback parsing from overall response if line items absent
    if not result["items"]:
        for field in summary_fields:
            ftype = (field.get("Type") or {}).get("Text")
            value = (field.get("ValueDetection") or {}).get("Text")
            if ftype and value is not None:
                if ftype.upper() in {"VENDOR_NAME", "MERCHANT_NAME", "SUPPLIER_NAME"} and not result["merchant"]:
                    result["merchant"] = value
                elif ftype.upper() in {"TAX", "TAX_AMOUNT", "SALES_TAX"} and not result["tax"]:
                    result["tax"] = value
                elif ftype.upper() in {"TOTAL", "AMOUNT_DUE", "INVOICE_RECEIPT_TOTAL"} and not result["total"]:
                    result["total"] = value

    return result
